import 'arc_poi_data.dart';
import '../models/arc_raid_intelligence_models.dart';

/// Evidence is a guide-supported loot possibility, never a guaranteed drop.
enum ArcPoiLootEvidence { namedGuide, lootPool }

class ArcPoiLootEntry {
  const ArcPoiLootEntry({required this.poiId, required this.itemName, required this.category, required this.evidence, required this.sourceUrl, required this.hint});
  final String poiId;
  final String itemName;
  final String category;
  final ArcPoiLootEvidence evidence;
  final String sourceUrl;
  final String hint;
  bool get isBlueprint => itemName.toLowerCase().contains('blueprint');
}

