  static final Map<String, List<ArcPoiLootEntry>> _byPoi = _buildIndex();

  static Map<String, List<ArcPoiLootEntry>> _buildIndex() {
    final index = <String, List<ArcPoiLootEntry>>{};
    for (final entry in entries) {
      (index[entry.poiId] ??= <ArcPoiLootEntry>[]).add(entry);
    }
    return index;
  }

  static List<ArcPoiLootEntry> forPoiId(String poiId) =>
      List<ArcPoiLootEntry>.unmodifiable(_byPoi[poiId] ?? const <ArcPoiLootEntry>[]);

  /// Strictly matches canonical POI names in the same map; never matches a region, cluster or substring.
  static List<ArcPoiLootEntry> forMarker(ArcRaidMapMarker marker) {
    if (marker.category != ArcRaidMapMarkerCategory.poi || marker.isCluster || marker.isBlueprintOpportunity) {
      return const <ArcPoiLootEntry>[];
    }
    final mapName = _mapName(marker.mapId);
    if (mapName == null) return const <ArcPoiLootEntry>[];
    final markerLabel = _normalise(marker.label);
    final markerPayload = marker.payloadId?.trim();
    for (final poi in ArcPoiDataStore.blueprintReportPoisForMap(mapName)) {
      if ((markerPayload != null && markerPayload == poi.id) ||
          (markerLabel.isNotEmpty && markerLabel == _normalise(poi.name))) {
        return forPoiId(poi.id);
      }
    }
    return const <ArcPoiLootEntry>[];
  }

  static String _normalise(String text) =>
      text.trim().toLowerCase().replaceAll(RegExp(r"[^a-z0-9]+"), " ").trim();

  static String? _mapName(String mapId) {
    switch (mapId.trim().toLowerCase().replaceAll(" ", "_")) {
      case 'buried_city': return ArcPoiDataStore.buriedCity;
      case 'dam_battlegrounds': return ArcPoiDataStore.damBattlegrounds;
      case 'blue_gate':
      case 'the_blue_gate': return ArcPoiDataStore.blueGate;
      case 'stella_montis': return ArcPoiDataStore.stellaMontis;
      case 'spaceport': return ArcPoiDataStore.spaceport;
      case 'riven_tides': return ArcPoiDataStore.rivenTides;
      default: return null;
    }
  }
